param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-wmma-error-20260916';$seed='D:\projects\AIMA-public-folded-half-projection-20260916-r3';$sha='35b3d6ca6f3f3052da8ab9bc2feb56dee735bdb8';$bundle='D:\projects\wmma-error-35b3d6c.bundle'
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $bundle '067ae145e559d5782fe174e572de0e5e011aed4b75529065b889ad1cbd364bbb'
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\wmma-error';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\wmma_error_probe.cpp';$exe=Join-Path $build 'wmma-error.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceInputs=@(@{file=$source;sha256=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant()})
$inputFile='D:\projects\wmma-error-input-r1.bin';$outputFile=Join-Path $build 'output-r1.bin'
Verify-File $inputFile '760ce36de6ba1a28edb2674909944291863d614c6f1e31a4641b9aac280b9ed1'
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; deterministic BF16 arithmetic cases within exponent80..174';input_payload=$inputFile;input_payload_sha256='760ce36de6ba1a28edb2674909944291863d614c6f1e31a4641b9aac280b9ed1';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Capture native zero-C BF16 WMMA bits across12 families,64 samples and four permutations. Two complete launches must agree. Verify finite results, every input and redzone before writing raw output. Python arbitrary integers later compare every error with relative-to-L1 powers19..27. This is a finite arithmetic diagnostic, not a universal hardware bound, model run or performance measurement.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=150
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$spec.arguments=@($inputFile,$outputFile);$timeout=120
}
$out=Join-Path $repo ('build\wmma-error-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne 1 -or $reports[0].cells -ne 786432 -or -not $reports[0].repeat_bit_parity -or -not $reports[0].redzones_pass -or -not $reports[0].immutable_inputs){throw 'Incomplete native diagnostic'}
 $manifest=@{input=@{file=$inputFile;bytes=(Get-Item $inputFile).Length;sha256=(Get-FileHash $inputFile -Algorithm SHA256).Hash.ToLowerInvariant()};output=@{file=$outputFile;bytes=(Get-Item $outputFile).Length;sha256=(Get-FileHash $outputFile -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'file-manifest.json'),($manifest|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}
